import os,sys,json,time,stat,datetime
base="/srv/projects"
sensitive={"private","secrets","credentials","sessions","data","project-secrets"}
result={"timestamp_utc":datetime.datetime.now(datetime.timezone.utc).isoformat(),"root":[],"locations":{},"projects":[]}
def one(path):
 try:
  with os.scandir(path) as it:
   return sorted([{"name":x.name,"type":("link" if x.is_symlink() else "dir" if x.is_dir(follow_symlinks=False) else "file")} for x in it],key=lambda a:a["name"].lower())
 except OSError as ex:return [{"error":type(ex).__name__}]
result["root"]=one("/")
for loc in ["/srv","/opt","/home/ubuntu","/root","/var/www","/var/lib","/usr/local","/etc/systemd/system","/etc/nginx/sites-enabled"]:
 result["locations"][loc]=one(loc)
try: projects=sorted(x for x in os.listdir(base) if os.path.isdir(os.path.join(base,x)) and not os.path.islink(os.path.join(base,x)))
except OSError:projects=[]
for project in projects:
 root=os.path.join(base,project)
 entry={"name":project,"root":root,"shallow":[],"folders":0,"files":0,"links":0,"errors":0,"top_types":{}}
 def err(e):entry["errors"]+=1
 for at,dirs,files in os.walk(root,followlinks=False,onerror=err):
  rel=os.path.relpath(at,root)
  depth=0 if rel=="." else rel.count(os.sep)+1
  entry["folders"]+=len(dirs)
  entry["files"]+=len(files)
  if depth<=2:
   for n in dirs+files:
    if depth and any(p.lower() in sensitive for p in rel.split(os.sep)):continue
    typ="dir" if n in dirs else "file"
    full=os.path.join(at,n)
    if os.path.islink(full):typ="link";entry["links"]+=1
    entry["shallow"].append([os.path.relpath(full,root),typ])
 entry["shallow"].sort()
 result["projects"].append(entry)
js=json.dumps(result,ensure_ascii=True,separators=(",",":"))
for pos in range(0,len(js),2500):
 sys.stdout.write(js[pos:pos+2500]);sys.stdout.flush();time.sleep(0.02)
sys.stdout.write("\n")
